// Prepares the OpenAI request plus LangSmith run IDs/timestamps for this execution.
const cfg = $('Config').first().json;

// UUID v7 (time-ordered), which LangSmith expects for run IDs.
function uuidv7(ms = Date.now()) {
  const r = (n) => Array.from({ length: n }, () => Math.floor(Math.random() * 16).toString(16)).join('');
  const ts = ms.toString(16).padStart(12, '0');
  const variant = '89ab'[Math.floor(Math.random() * 4)];
  return `${ts.slice(0, 8)}-${ts.slice(8, 12)}-7${r(3)}-${variant}${r(3)}-${r(12)}`;
}

const now = Date.now();
const messages = [
  { role: 'system', content: 'You are Mira, an AI project intelligence assistant for PMs/TPMs at Nexora. Reply in one short sentence.' },
  { role: 'user', content: cfg.userQuery },
];

return [{
  json: {
    traceId: uuidv7(now),
    llmRunId: uuidv7(now + 1),
    startTime: new Date(now).toISOString(),
    llmStartTime: new Date(now + 1).toISOString(),
    query: cfg.userQuery,
    model: cfg.model,
    project: cfg.langsmithProject,
    asOfDate: cfg.asOfDate,
    openaiRequest: { model: cfg.model, temperature: 0.2, messages },
  },
}];

// Converts the OpenAI response into a LangSmith trace: root chain run + child llm run.
const ctx = $('Start Trace').first().json;
const resp = $input.first().json;
const endTime = new Date().toISOString();

// LangSmith dotted_order segment: YYYYMMDDTHHMMSSffffffZ + run id
const dottedTs = (iso) => iso.replace(/[-:]/g, '').replace('.', '').replace('Z', '000Z');

const answer = resp.choices?.[0]?.message?.content ?? '';
const usage = resp.usage ?? {};
const usageMetadata = {
  input_tokens: usage.prompt_tokens ?? 0,
  output_tokens: usage.completion_tokens ?? 0,
  total_tokens: usage.total_tokens ?? 0,
};

const rootDotted = dottedTs(ctx.startTime) + ctx.traceId;

const root = {
  id: ctx.traceId,
  trace_id: ctx.traceId,
  dotted_order: rootDotted,
  name: 'Mira',
  run_type: 'chain',
  inputs: { query: ctx.query },
  outputs: { answer },
  start_time: ctx.startTime,
  end_time: endTime,
  session_name: ctx.project,
  tags: ['mira', 'step1-smoke-test'],
  extra: { metadata: { as_of_date: ctx.asOfDate, n8n_execution_id: $execution.id } },
};

const llm = {
  id: ctx.llmRunId,
  trace_id: ctx.traceId,
  parent_run_id: ctx.traceId,
  dotted_order: `${rootDotted}.${dottedTs(ctx.llmStartTime)}${ctx.llmRunId}`,
  name: 'OpenAI Chat',
  run_type: 'llm',
  inputs: { messages: ctx.openaiRequest.messages },
  outputs: { ...resp, usage_metadata: usageMetadata },
  start_time: ctx.llmStartTime,
  end_time: endTime,
  session_name: ctx.project,
  extra: {
    metadata: { ls_provider: 'openai', ls_model_name: ctx.model, ls_model_type: 'chat', ls_temperature: 0.2 },
    invocation_params: { model: ctx.model, temperature: 0.2 },
  },
};

return [{ json: { answer, usage: usageMetadata, traceId: ctx.traceId, batch: { post: [root, llm] } } }];
